class EffectLifecycleTests {
 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
 static int passed,failed;static List<Tuple<Combat.CombatUnit.EstimatedState,Effect>> projected;
 static bool rebalance;static int mutationChecks;
 static Dictionary<string,JObject> Effects,Powers,Modifiers,PowerModifiers;
 static int Main(string[] a){rebalance=a.Length>1&&a[1]=="rebalance";AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{var p=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,new AssemblyName(e.Name).Name+".dll");if(!File.Exists(p))p=Path.Combine(a[0],"Star Renegades_Data/Managed",new AssemblyName(e.Name).Name+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};return Run();}
 [MethodImpl(MethodImplOptions.NoInlining)] static int Run(){
 projected=new List<Tuple<Combat.CombatUnit.EstimatedState,Effect>>();Effects=Rows("Effects");Powers=Rows("Powers");Modifiers=Rows("UnitModifiers");PowerModifiers=Rows("PowerModifiers");
 var h=new Harmony("audit.priority2.effects");SRBugfix.ReflectionPreviewFix.Enabled=true;h.Patch(SRBugfix.ReflectionPreviewFix.ResolveTarget(),transpiler:new HarmonyMethod(typeof(SRBugfix.ReflectionPreviewFix).GetMethod("Transpile",F)));SRBugfix.ProjectedEffectFix.Enabled=true;SRBugfix.ProjectedEffectFix.Install(h);SRBugfix.EffectLifecycleFix.Enabled=true;SRBugfix.EffectLifecycleFix.Install(h);SRBugfix.ReflectionPreviewFix.InstallReactionHooks(h);SRBugfix.ComboEffectFix.Enabled=true;SRBugfix.ComboEffectFix.Install(h);
 SRBugfix.ResourceForecastFix.Enabled=true;SRBugfix.ResourceForecastFix.Install(h);
 try {
 Test("NativeSourceCleanseCancelsDefenseDebuff",()=>{var f=new Fixture();f.LivePartner();var e=LoadEffect(f,"effDebuffHealthDef25Rds1");f.Partner.Unit.AddEffect(e);AttachCombatEffect(f,f.Partner,e,f.Partner);Equal(f.Partner.Unit.HealthDefense,-25,"native applied defense");var cp=LoadPower(f,"hGrdSpeCombo",f.Partner);var r=Execute(f,cp,f.Third);Check(r.Any(x=>x.type==Combat.CombatPowerResult.Type.CancelEffect&&x.effect==e&&x.target==f.Partner),"execution did not cancel source defense debuff");Equal(f.Partner.Unit.HealthDefense,0,"native removed defense");});
 Test("ForecastSourceCleanseCancelsDefenseDebuff",()=>{var f=new Fixture();f.LivePartner();var e=LoadEffect(f,"effDebuffHealthDef25Rds1");var s=States(f);s[f.Partner].ApplyEffect(e,f.Partner);Equal(s[f.Partner].HealthDefense,-25,"projected defense setup");var cp=LoadPower(f,"hGrdSpeCombo",f.Partner);Forecast(f,s,cp,new List<Combat.CombatUnit>{f.Third});Equal(s[f.Partner].HealthDefense,0,"source defense debuff survived Guardian Spectre combo");Equal(f.Partner.Unit.Effects.Count,0,"forecast changed live effects");});
 Test("NativeDefendImmunityBlocksDebuff",()=>{var f=new Fixture();f.LivePartner();var defend=LoadEffect(f,"effDefend");var debuff=LoadEffect(f,"effDebuffHealthDef25Rds1");f.Partner.Unit.AddEffect(defend);Check(!f.Partner.Unit.CanApplyEffect(debuff),"native Defend failed to grant debuff immunity");Equal(f.Partner.Unit.HealthDefense,40,"native Defend defense");});
 Test("ForecastDefendImmunityBlocksDebuff",()=>{var f=new Fixture();f.LivePartner();var defend=LoadEffect(f,"effDefend");var debuff=LoadEffect(f,"effDebuffHealthDef25Rds1");var s=States(f);s[f.Partner].ApplyEffect(defend,f.Partner);s[f.Partner].ApplyEffect(debuff,f.Source);Equal(s[f.Partner].HealthDefense,40,"projected Defend allowed debuff");Equal(f.Partner.Unit.Effects.Count,0,"forecast changed live effects");});
 Test("NativeGuardianSpectreCleansesAllyDebuff",()=>{var f=new Fixture();f.LivePartner();var e=LoadEffect(f,"effDebuffHealthDef25Rds1");f.Partner.Unit.AddEffect(e);AttachCombatEffect(f,f.Partner,e,f.Partner);var cp=LoadPower(f,"hGrdSpeCombo",f.Source);var r=Execute(f,cp,f.Third);Check(r.Any(x=>x.type==Combat.CombatPowerResult.Type.CancelEffect&&x.effect==e&&x.target==f.Partner),"native ally cleanse omitted");Equal(f.Partner.Unit.HealthDefense,0,"native ally cleanse retained defense");});
 Test("ForecastGuardianSpectreCleansesAllyDebuff",()=>{var f=new Fixture();f.LivePartner();var e=LoadEffect(f,"effDebuffHealthDef25Rds1");var s=States(f);s[f.Partner].ApplyEffect(e,f.Partner);var cp=LoadPower(f,"hGrdSpeCombo",f.Source);Forecast(f,s,cp,new List<Combat.CombatUnit>{f.Third});Equal(s[f.Partner].HealthDefense,0,"untargeted ally cleanse retained defense debuff");Equal(f.Partner.Unit.Effects.Count,0,"forecast changed live effects");});

 Test("NativeGuardBreakRemovesOtherUnitsTetheredGuard",()=>{var f=new Fixture();f.LivePartner();Prepare(f,f.Source);var guard=LoadPower(f,"hAegGuard",f.Partner);Execute(f,guard,f.Source);Check(f.Source.Unit.Effects.Any(x=>x.Effect.ID=="effGuardTarget"),"native initial guarded target missing");Equal(f.Partner.Unit.HealthDefense,20,"native initial guard defense");var cp=LoadPower(f,"hJugBreakGuard",f.Third);Execute(f,cp,f.Partner);Equal(f.Partner.Unit.HealthDefense,0,"native guard break retained tethered defense");Check(!f.Source.Unit.Effects.Any(x=>x.Effect.ID=="effGuardTarget"),"native guard break retained other unit guard");});
 Test("ForecastGuardBreakRemovesOtherUnitsTetheredGuard",()=>{var f=new Fixture();f.LivePartner();Prepare(f,f.Source);var guard=LoadPower(f,"hAegGuard",f.Partner);Execute(f,guard,f.Source);var s=States(f);var cp=LoadPower(f,"hJugBreakGuard",f.Third);Forecast(f,s,cp,new List<Combat.CombatUnit>{f.Partner});Equal(s[f.Partner].HealthDefense,0,"forecast guard break retained tethered defense");var g=new List<Combat.CombatUnit>();Check(!s[f.Source].IsGuarded(s,ref g),"forecast retained other unit guard");});
 Test("NativeAnyActionTagConsumesInstantOnDefend",()=>{var f=new Fixture();f.LivePartner();var e=LoadEffect(f,"hEmpNextActionInstant");f.Partner.Unit.AddEffect(e);AttachCombatEffect(f,f.Partner,e,f.Partner);var cp=LoadPower(f,"hComDefend",f.Partner);Execute(f,cp,f.Partner);Check(!f.Partner.Unit.HasEffect(e),"native any action did not consume instant");});
 Test("ForecastAnyActionTagConsumesInstantOnDefend",()=>{var f=new Fixture();f.LivePartner();var e=LoadEffect(f,"hEmpNextActionInstant");var s=States(f);s[f.Partner].ApplyEffect(e,f.Partner);var cp=LoadPower(f,"hComDefend",f.Partner);Forecast(f,s,cp,new List<Combat.CombatUnit>{f.Partner});Check(!SRBugfix.ProjectedEffectFix.HasEffectForEstimate(f.Partner.Unit,e,s[f.Partner]),"forecast any action did not consume instant");});
 Test("NativeAttackTagConsumesStealth",()=>{var f=new Fixture();f.LivePartner();var e=LoadEffect(f,"effStealth1");f.Partner.Unit.AddEffect(e);AttachCombatEffect(f,f.Partner,e,f.Partner);Execute(f,LoadPower(f,"hAegBash",f.Partner),f.Third);Check(!f.Partner.Unit.HasEffect(e),"native attack did not consume stealth");});
 Test("ForecastAttackTagConsumesStealth",()=>{var f=new Fixture();f.LivePartner();var e=LoadEffect(f,"effStealth1");var s=States(f);s[f.Partner].ApplyEffect(e,f.Partner);Forecast(f,s,LoadPower(f,"hAegBash",f.Partner),new List<Combat.CombatUnit>{f.Third});Check(!SRBugfix.ProjectedEffectFix.HasEffectForEstimate(f.Partner.Unit,e,s[f.Partner]),"forecast attack retained stealth");});

 Test("NativeRemovedDefendImmunityAllowsNextDebuff",()=>{var f=new Fixture();f.LivePartner();var defend=LoadEffect(f,"effDefend");var debuff=LoadEffect(f,"effDebuffHealthDef25Rds1");f.Partner.Unit.AddEffect(defend);AttachCombatEffect(f,f.Partner,defend,f.Partner);Execute(f,LoadPower(f,"eWraInterrupt",f.Third),f.Partner);Check(!f.Partner.Unit.HasEffect(defend),"native interrupt did not cancel Defend");Check(f.Partner.Unit.CanApplyEffect(debuff),"native cancelled immunity retained");f.Partner.Unit.AddEffect(debuff);Equal(f.Partner.Unit.HealthDefense,-25,"native later debuff rejected");});
 Test("ForecastRemovedDefendImmunityAllowsNextDebuff",()=>{var f=new Fixture();f.LivePartner();var defend=LoadEffect(f,"effDefend");var debuff=LoadEffect(f,"effDebuffHealthDef25Rds1");f.Partner.Unit.AddEffect(defend);AttachCombatEffect(f,f.Partner,defend,f.Partner);var s=States(f);Forecast(f,s,LoadPower(f,"eWraInterrupt",f.Third),new List<Combat.CombatUnit>{f.Partner});Check(!SRBugfix.ProjectedEffectFix.HasEffectForEstimate(f.Partner.Unit,defend,s[f.Partner]),"projected interrupt did not cancel Defend");s[f.Partner].ApplyEffect(debuff,f.Third);Equal(s[f.Partner].HealthDefense,-25,"forecast consulted cancelled live immunity");});
 Test("NativeGuardRefreshChangesBestower",()=>{var f=new Fixture();f.LivePartner();Prepare(f,f.Source);MakeAlly(f,f.Third);Prepare(f,f.Third);Execute(f,LoadPower(f,"hAegGuard",f.Partner),f.Source);Execute(f,LoadPower(f,"hAegGuard",f.Third),f.Source);var states=States(f);var gs=new List<Combat.CombatUnit>();Check(states[f.Source].IsGuarded(states,ref gs),"native refreshed guard missing");Check(gs.Count==1&&gs[0]==f.Third,"native refresh retained old bestower");});
 Test("ForecastGuardRefreshChangesBestower",()=>{var f=new Fixture();f.LivePartner();Prepare(f,f.Source);MakeAlly(f,f.Third);Prepare(f,f.Third);Execute(f,LoadPower(f,"hAegGuard",f.Partner),f.Source);var states=States(f);Forecast(f,states,LoadPower(f,"hAegGuard",f.Third),new List<Combat.CombatUnit>{f.Source});var gs=new List<Combat.CombatUnit>();Check(states[f.Source].IsGuarded(states,ref gs),"forecast refreshed guard missing");Check(gs.Count==1&&gs[0]==f.Third,"forecast refresh retained old bestower");});
 Test("NativeSimpleDefendPreservesAnyActionBuff",()=>{var f=new Fixture();f.LivePartner();var e=LoadEffect(f,"hEmpNextActionInstant");f.Partner.Unit.AddEffect(e);AttachCombatEffect(f,f.Partner,e,f.Partner);Execute(f,LoadPower(f,"hDef",f.Partner),f.Partner);Check(f.Partner.Unit.HasEffect(e),"native generic Defend consumed action-tagged buff");});
 Test("ForecastSimpleDefendPreservesAnyActionBuff",()=>{var f=new Fixture();f.LivePartner();var e=LoadEffect(f,"hEmpNextActionInstant");var states=States(f);states[f.Partner].ApplyEffect(e,f.Partner);Forecast(f,states,LoadPower(f,"hDef",f.Partner),new List<Combat.CombatUnit>{f.Partner});Check(SRBugfix.ProjectedEffectFix.HasEffectForEstimate(f.Partner.Unit,e,states[f.Partner]),"forecast generic Defend consumed action-tagged buff");});

 Test("NativeCleansedSourceTakesConfiguredDamage",()=>{var f=new Fixture();f.LivePartner();var e=LoadEffect(f,"effDebuffHealthDef25Rds1");f.Partner.Unit.AddEffect(e);AttachCombatEffect(f,f.Partner,e,f.Partner);Execute(f,LoadPower(f,"hGrdSpeCombo",f.Partner),f.Third);Execute(f,LoadPower(f,"hAegBash",f.Third),f.Partner);Equal(f.Partner.Unit.CurrentHealth,rebalance?76:80,"native later hit after source cleanse");});
 Test("ForecastCleansedSourceTakesConfiguredDamage",()=>{var f=new Fixture();f.LivePartner();var s=States(f);s[f.Partner].ApplyEffect(LoadEffect(f,"effDebuffHealthDef25Rds1"),f.Partner);Forecast(f,s,LoadPower(f,"hGrdSpeCombo",f.Partner),new List<Combat.CombatUnit>{f.Third});Forecast(f,s,LoadPower(f,"hAegBash",f.Third),new List<Combat.CombatUnit>{f.Partner});Equal(s[f.Partner].health,rebalance?76:80,"forecast later hit after source cleanse");});
 Test("NativeGuardedUnitDefendsItself",()=>{var f=new Fixture();f.LivePartner();Prepare(f,f.Source);Execute(f,LoadPower(f,"hAegGuard",f.Partner),f.Source);Execute(f,LoadPower(f,"hDef",f.Source),f.Source);Equal(f.Source.Unit.HealthDefense,40,"native guarded unit own Defend");Equal(f.Partner.Unit.HealthDefense,20,"native guardian wrongly received Defend");});
 Test("ForecastGuardedUnitDefendsItself",()=>{var f=new Fixture();f.LivePartner();Prepare(f,f.Source);Execute(f,LoadPower(f,"hAegGuard",f.Partner),f.Source);var s=States(f);Forecast(f,s,LoadPower(f,"hDef",f.Source),new List<Combat.CombatUnit>{f.Source});Equal(s[f.Source].HealthDefense,40,"forecast guarded unit own Defend");Equal(s[f.Partner].HealthDefense,20,"forecast guardian wrongly received Defend");});
 Test("ForecastDirectGuardRefreshChangesBestower",()=>{var f=new Fixture();f.LivePartner();Prepare(f,f.Source);MakeAlly(f,f.Third);Prepare(f,f.Third);Execute(f,LoadPower(f,"hAegGuard",f.Partner),f.Source);var states=States(f);states[f.Source].ApplyEffect(LoadEffect(f,"effGuardTarget"),f.Third);var gs=new List<Combat.CombatUnit>();Check(states[f.Source].IsGuarded(states,ref gs),"forecast direct refreshed guard missing");Check(gs.Count==1&&gs[0]==f.Third,"forecast direct refresh retained old bestower");});

 Test("ForecastGuardBreakStopsOtherUnitRedirect",()=>{var f=new Fixture();f.LivePartner();Prepare(f,f.Source);Execute(f,LoadPower(f,"hAegGuard",f.Partner),f.Source);var states=States(f);Forecast(f,states,LoadPower(f,"hJugBreakGuard",f.Third),new List<Combat.CombatUnit>{f.Partner});var guardians=new List<Combat.CombatUnit>();Check(!states[f.Source].IsGuarded(states,ref guardians),"expected no guardian after break; actual="+String.Join(",",guardians.Select(u=>u.ID)));});
 Test("ProjectedApplyDoesNotMutateLiveUnits",()=>{var f=new Fixture();f.LivePartner();var snapshot=Snapshot(f);var states=States(f);states[f.Partner].ApplyEffect(LoadEffect(f,"effDefend"),f.Partner);states[f.Partner].ApplyEffect(LoadEffect(f,"effDebuffHealthDef25Rds1"),f.Source);Check(snapshot==Snapshot(f),"direct projected ApplyEffect mutated unit");mutationChecks++;});

 Test("NativeBestowerCoverBreakRemovesAllyCounter",()=>{var f=new Fixture();f.LivePartner();Prepare(f,f.Source);LoadPower(f,"hEnfCoverAttack",f.Partner);Execute(f,LoadPower(f,"hEnfCover",f.Partner),f.Source);Equal(f.Source.Unit.ReturnFireEffects.Count,1,"native cover counter setup");Execute(f,LoadPower(f,"hSabInterrupt",f.Third),f.Partner);Equal(f.Source.Unit.ReturnFireEffects.Count,0,"native bestower break retained ally counter");});
 Test("ForecastBestowerCoverBreakRemovesAllyCounter",()=>{var f=new Fixture();f.LivePartner();Prepare(f,f.Source);LoadPower(f,"hEnfCoverAttack",f.Partner);Execute(f,LoadPower(f,"hEnfCover",f.Partner),f.Source);var s=States(f);Forecast(f,s,LoadPower(f,"hSabInterrupt",f.Third),new List<Combat.CombatUnit>{f.Partner});Equal(s[f.Source].returnFireEffects.Count,0,"forecast bestower break retained ally counter");});
 Test("NativeBestowerOverwatchBreakRemovesEnemyTrigger",()=>{var f=new Fixture();f.LivePartner();Prepare(f,f.Third);LoadPower(f,"hMarOverwatchShot",f.Partner);Execute(f,LoadPower(f,"hMarOverwatch",f.Partner),f.Third);Equal(f.Third.Unit.OverwatchEffects.Count,1,"native overwatch setup");Execute(f,LoadPower(f,"hSabInterrupt",f.Third),f.Partner);Equal(f.Third.Unit.OverwatchEffects.Count,0,"native bestower break retained enemy overwatch trigger");});
