 Test("ProjectedGuardCreationThenBreakRemovesTethers",()=>{var f=new Fixture();f.LivePartner();Prepare(f,f.Source);var states=States(f);Forecast(f,states,LoadPower(f,"hAegGuard",f.Partner),new List<Combat.CombatUnit>{f.Source});Equal(states[f.Partner].HealthDefense,20,"projected initial guard defense");Forecast(f,states,LoadPower(f,"hJugBreakGuard",f.Third),new List<Combat.CombatUnit>{f.Partner});Equal(states[f.Partner].HealthDefense,0,"projected new tether retained defense");var gs=new List<Combat.CombatUnit>();Check(!states[f.Source].IsGuarded(states,ref gs),"projected new tether retained guard");});
 Test("ProjectedSourceGrantOnceAtEndOfMultiHit",()=>{var f=new Fixture();f.LivePartner();var states=States(f);var cp=LoadPower(f,"hComDefend",f.Partner);states[f.Partner].EstimateSourceEffects(cp);Invoke(f.Combat,"EstimatePowerAgainstTargets",states,cp,new Dictionary<Combat.CombatUnit,Combat.UnitResults>(),new List<Combat.CombatUnit>{f.Partner},true,false,null,null);Equal(states[f.Partner].HealthDefense,0,"source grant occurred before final hit");Invoke(f.Combat,"EstimatePowerAgainstTargets",states,cp,new Dictionary<Combat.CombatUnit,Combat.UnitResults>(),new List<Combat.CombatUnit>{f.Partner},false,true,null,null);Equal(states[f.Partner].HealthDefense,40,"source grant missing/duplicated at final hit");});
 Test("IntrinsicAndDefendDuplicateImmunitySurvivesDefendCancellation",()=>{var f=new Fixture();f.LivePartner();f.Partner.Unit.UnitClassData.effectImmunitiesByTag=new[]{"debuff"};var defend=LoadEffect(f,"effDefend");f.Partner.Unit.AddEffect(defend);AttachCombatEffect(f,f.Partner,defend,f.Partner);var states=States(f);Forecast(f,states,LoadPower(f,"eWraInterrupt",f.Third),new List<Combat.CombatUnit>{f.Partner});states[f.Partner].ApplyEffect(LoadEffect(f,"effDebuffHealthDef25Rds1"),f.Third);Equal(states[f.Partner].HealthDefense,0,"intrinsic immunity removed with effect immunity");});
 Test("ForecastExceptionDoesNotGrantDeferredSourceBuffOrLeakContext",()=>{var f=new Fixture();f.LivePartner();var states=States(f);var cp=LoadPower(f,"hComDefend",f.Partner);Set(f.Game,"currentDifficulty",null);bool threw=false;try{Forecast(f,states,cp,new List<Combat.CombatUnit>{f.Partner});}catch(NullReferenceException){threw=true;}Check(threw,"native fault did not throw");Equal(states[f.Partner].HealthDefense,0,"fault granted deferred source defense");Set(f.Game,"currentDifficulty",new DifficultyData{id="default"});Forecast(f,states,cp,new List<Combat.CombatUnit>{f.Partner});Equal(states[f.Partner].HealthDefense,40,"retry failed or duplicated defense");var other=new Fixture();other.LivePartner();var otherStates=States(other);Forecast(other,otherStates,LoadPower(other,"hDef",other.Partner),new List<Combat.CombatUnit>{other.Partner});Equal(otherStates[other.Partner].HealthDefense,40,"previous context leaked into another scenario");});
 Test("DisabledLifecyclePreservesNativeSourceGrantAndStaleSourceCancellation",()=>{SRBugfix.EffectLifecycleFix.Enabled=false;try{var f=new Fixture();f.LivePartner();var states=States(f);var cp=LoadPower(f,"hComDefend",f.Partner);states[f.Partner].EstimateSourceEffects(cp);Equal(states[f.Partner].HealthDefense,40,"disabled lifecycle deferred native source grant");var instant=LoadEffect(f,"hEmpNextActionInstant");states[f.Partner].ApplyEffect(instant,f.Partner);Forecast(f,states,cp,new List<Combat.CombatUnit>{f.Partner});Check(SRBugfix.ProjectedEffectFix.HasEffectForEstimate(f.Partner.Unit,instant,states[f.Partner]),"disabled lifecycle changed baseline source cancellation");}finally{SRBugfix.EffectLifecycleFix.Enabled=true;}});
 Test("UngroupedDefendEffectsKeepBothWithoutDuplicateRefresh",()=>{var f=new Fixture();f.LivePartner();var states=States(f);states[f.Partner].ApplyEffect(LoadEffect(f,"effDefend25"),f.Partner);states[f.Partner].ApplyEffect(LoadEffect(f,"effDefend"),f.Partner);states[f.Partner].ApplyEffect(LoadEffect(f,"effDefend"),f.Partner);Equal(states[f.Partner].HealthDefense,60,"ungrouped independent effects or refresh changed defense");});

 Test("NativeUngroupedDefendEffectsKeepBothWithoutDuplicateRefresh",()=>{var f=new Fixture();f.LivePartner();f.Partner.Unit.AddEffect(LoadEffect(f,"effDefend25"));f.Partner.Unit.AddEffect(LoadEffect(f,"effDefend"));f.Partner.Unit.AddEffect(LoadEffect(f,"effDefend"));Equal(f.Partner.Unit.HealthDefense,60,"native ungrouped defend values");});
 Test("PublicScenarioAppliesDeferredSourceGrantOnce",()=>{var f=new Fixture();f.LivePartner();var cp=LoadPower(f,"hComDefend",f.Partner);observedStates=null;var method=SRBugfix.ComboEffectFix.ResolveForecastTarget();h.Patch(method,postfix:new HarmonyMethod(typeof(EffectLifecycleTests).GetMethod("ObserveAction",F)){priority=Priority.Last});try{var snapshot=Snapshot(f);f.Combat.GetPowerScenario(cp,new Combat.CombatUnitPower.TargetGroup{f.Partner.Position});Check(snapshot==Snapshot(f),"public scenario mutated live unit");Check(observedStates!=null,"public scenario did not reach action forecast");Equal(observedStates[f.Partner].HealthDefense,40,"public scenario missing/duplicate deferred source grant");}finally{h.Unpatch(method,typeof(EffectLifecycleTests).GetMethod("ObserveAction",F));}});

 Test("NestedNativeCallbackForecastKeepsSeparateLifecycleContexts",()=>{var outer=new Fixture();outer.LivePartner();Prepare(outer,outer.Source);var inner=new Fixture();inner.LivePartner();var outerStates=States(outer);var innerStates=States(inner);var cp=LoadPower(outer,"hAegGuard",outer.Partner);outerStates[outer.Partner].EstimateSourceEffects(cp);Action<Combat.CombatUnit> callback=u=>Forecast(inner,innerStates,LoadPower(inner,"hDef",inner.Partner),new List<Combat.CombatUnit>{inner.Partner});Invoke(outer.Combat,"EstimatePowerAgainstTargets",outerStates,cp,new Dictionary<Combat.CombatUnit,Combat.UnitResults>(),new List<Combat.CombatUnit>{outer.Source},true,true,callback,null);Equal(outerStates[outer.Partner].HealthDefense,20,"outer source grant changed by nested forecast");Equal(innerStates[inner.Partner].HealthDefense,40,"inner source grant missing");Forecast(outer,outerStates,LoadPower(outer,"hJugBreakGuard",outer.Third),new List<Combat.CombatUnit>{outer.Partner});var gs=new List<Combat.CombatUnit>();Check(!outerStates[outer.Source].IsGuarded(outerStates,ref gs),"outer tether context lost after nested forecast");Equal(innerStates[inner.Partner].HealthDefense,40,"outer cancellation crossed inner scenario");});
